// worker — это горутина-воркер, которая обрабатывает задачи из канала jobs
// и отправляет результаты в канал results.
// wg — указатель на WaitGroup для синхронизации завершения всех воркеров.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	// defer wg.Done() гарантирует, что счётчик WaitGroup будет уменьшен
	// при выходе из функции, даже если произойдёт паника или ошибка.
	// Это позволяет основному потоку дождаться завершения всех воркеров.
	defer wg.Done()

	// Бесконечный цикл чтения задач из канала jobs.
	// Цикл завершится автоматически, когда канал jobs будет закрыт
	// (range по закрытому каналу возвращает false).
	for j := range jobs {
		// Вызываем функцию process для обработки полученной задачи j.
		// process возвращает результат r и ошибку err.
		r, err := process(j)

		// Если при обработке задачи возникла ошибка, логируем её
		// и переходим к следующей задаче, не отправляя результат.
		if err != nil {
			log.Printf("job %d: %v", j.ID, err)
			continue
		}

		// Отправляем успешный результат r в канал results.
		// Если канал results заполнен или не читается, эта операция
		// заблокирует горутину до тех пор, пока не появится возможность
		// отправить значение.
		results <- r
	}
}
```

