/**
 * Потокобезопасная версия стандартной функции getOrPut для MutableMap.
 *
 * @param K тип ключей в мапе
 * @param V тип значений в мапе
 * @param key ключ, по которому нужно получить значение
 * @param factory лямбда-функция, создающая новое значение, если ключ отсутствует
 * @return существующее значение по ключу или новое, созданное фабрикой
 */
fun <K, V> MutableMap<K, V>.getOrPutSafe(key: K, factory: () -> V): V =
    // Синхронизируем доступ к объекту мапы, чтобы избежать гонок данных
    // при одновременном вызове из разных потоков
    synchronized(this) {
        // Пытаемся получить существующее значение по ключу
        // Если значение null (ключ отсутствует), вызываем фабрику для создания нового
        this[key] ?: factory()
            // .also позволяет выполнить побочный эффект (сохранение нового значения в мапу)
            // и вернуть само созданное значение
            .also { this[key] = it }
    }
