/// Парсит строку формата "key1=value1;key2=value2;..." в HashMap.
/// Ключи приводятся к нижнему регистру и обрезаются по краям,
/// значения также обрезаются по краям.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // Разбиваем входную строку по символу ';' на части (пары ключ-значение)
        .filter_map(|p| p.split_once('=')) // Для каждой части пытаемся разделить её по первому '=';
                                           // если '=' нет, часть игнорируется (filter_map пропускает None)
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // Обрезаем пробелы вокруг ключа и значения,
                                                                       // приводим ключ к нижнему регистру,
                                                                       // формируем пару (String, String)
        .collect() // Собираем все пары в HashMap<String, String>
}
